{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Amrinone, an amino-pyridinone with a pyridine substituent, has 90-95% oral bioavailability in healthy subjects, supporting high F for the query's amino-oxo heteroaromatic pyridine-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Enprofylline, a xanthine-like fused heterocycle, shows 94% absolute oral bioavailability in humans, supporting high absorption for the query's purine-like bicyclic core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nicorandil, a polar pyridine carboxamide, has 79 ± 9% absolute oral bioavailability in healthy volunteers, demonstrating that pyridine-containing polar small molecules can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nicotinic acid, a simple pyridine-3-carboxylic acid, has about 90% systemic availability in humans, indicating the pyridine moiety itself is not a barrier to high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Risedronate has very low oral bioavailability (<0.5%) in humans, but this contradictory evidence has low transferability because its multiple phosphonic acid groups make it highly charged and poorly permeable, unlike the neutral query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: multiple transferable experimental analogues with pyridine and purine/xanthine-like heteroaromatic scaffolds show oral bioavailability of 66-95%, well above the 20% threshold. The only low-F analogue, risedronate, is a bisphosphonate whose extreme polarity and ionization do not transfer to the neutral, lower-TPSA query. Therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Morgan similarities to evidence molecules are low to moderate, limiting quantitative transferability.",
    "No query-specific permeability, metabolic stability, or transporter data are available.",
    "The effect of the 3-pyridylmethyl substituent on absorption is inferred rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

